// First-party byte-constructed ELF controls for hp_elf.c. The frozen local
// Python controls supplied acceptance cases, not generated bytes or C code.
// These fixtures never invoke a compiler, assembler, executable or subprocess.
#include "hp_elf.h"

#include <assert.h>
#include <elf.h>
#include <inttypes.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define BUSTER_CONTROL_CAPACITY 32768U
#define BUSTER_CONTROL_SECTION_COUNT 12U
#define BUSTER_CONTROL_SYMBOL_COUNT 7U
#define BUSTER_ARRAY_COUNT(values) (sizeof(values) / sizeof((values)[0]))
#define BUSTER_CONTROL_HOT ".text.buster_checker"

_Static_assert(sizeof(Elf64_Ehdr) == 64, "ELF64 header layout");
_Static_assert(sizeof(Elf64_Shdr) == 64, "ELF64 section layout");
_Static_assert(sizeof(Elf64_Sym) == 24, "ELF64 symbol layout");
_Static_assert(sizeof(Elf64_Rela) == 24, "ELF64 RELA layout");

typedef enum ControlSection
{
    BUSTER_SECTION_NULL,
    BUSTER_SECTION_HOT,
    BUSTER_SECTION_DATA,
    BUSTER_SECTION_BSS,
    BUSTER_SECTION_SYMTAB,
    BUSTER_SECTION_STRTAB,
    BUSTER_SECTION_SHSTRTAB,
    BUSTER_SECTION_RELA_HOT,
    BUSTER_SECTION_RELA_DATA,
    BUSTER_SECTION_ADDRSIG,
    BUSTER_SECTION_COMMENT,
    BUSTER_SECTION_STACK
} ControlSection;

typedef enum ControlSymbol
{
    BUSTER_SYMBOL_NULL,
    BUSTER_SYMBOL_FILE,
    BUSTER_SYMBOL_SECTION,
    BUSTER_SYMBOL_FOO,
    BUSTER_SYMBOL_DATA,
    BUSTER_SYMBOL_EXTERNAL,
    BUSTER_SYMBOL_ALIAS
} ControlSymbol;

typedef enum ControlFault
{
    BUSTER_FAULT_NONE,
    BUSTER_FAULT_HOT_BYTE,
    BUSTER_FAULT_PREFIX_BYTE,
    BUSTER_FAULT_ALIGNMENT,
    BUSTER_FAULT_SYMBOL_OFFSET,
    BUSTER_FAULT_SYMBOL_SIZE,
    BUSTER_FAULT_SYMBOL_VISIBILITY,
    BUSTER_FAULT_RELOC_OFFSET,
    BUSTER_FAULT_UNKNOWN_RELOCATION,
    BUSTER_FAULT_WRONG_TARGET,
    BUSTER_FAULT_FILE_REFERENCED,
    BUSTER_FAULT_OVERLAP,
    BUSTER_FAULT_HOT_SECTION_GOT,
    BUSTER_FAULT_PC_SECTION,
    BUSTER_FAULT_SECTION_ADDEND,
    BUSTER_FAULT_SECTION_ADDEND_OUTSIDE,
    BUSTER_FAULT_NAMED_ADDEND,
    BUSTER_FAULT_ADDRSIG_TARGET,
    BUSTER_FAULT_MISSING_ADDRSIG,
    BUSTER_FAULT_MISSING_STACK_NOTE,
    BUSTER_FAULT_EXEC_STACK,
    BUSTER_FAULT_DATA_BYTE,
    BUSTER_FAULT_BSS_SIZE,
    BUSTER_FAULT_ALLOC_SYMTAB,
    BUSTER_FAULT_REL,
    BUSTER_FAULT_GROUP,
    BUSTER_FAULT_BAD_MAGIC,
    BUSTER_FAULT_TRUNCATE,
    BUSTER_FAULT_ALIAS,
    BUSTER_FAULT_AMBIGUOUS_SYMBOL,
    BUSTER_FAULT_TLSDESC_34,
    BUSTER_FAULT_TLSDESC_35,
    BUSTER_FAULT_TLSDESC_36,
    BUSTER_FAULT_ADDRSIG_DUPLICATE_LOSS,
    BUSTER_FAULT_ADDRSIG_TRUNCATED,
    BUSTER_FAULT_ADDRSIG_OVERFLOW,
    BUSTER_FAULT_ADDRSIG_BAD_SYMBOL,
    BUSTER_FAULT_ALLOC_COMMENT,
    BUSTER_FAULT_UNKNOWN_LINKED_METADATA,
    BUSTER_FAULT_ALLOC_RELA,
    BUSTER_FAULT_ALLOC_STRTAB,
    BUSTER_FAULT_HOT_SYMBOL_UNDERFLOW,
    BUSTER_FAULT_HOT_SYMBOL_OVERFLOW,
    BUSTER_FAULT_RELOC_OVERFLOW,
    BUSTER_FAULT_SECTION_ADDEND_OVERFLOW
} ControlFault;

typedef struct ControlBuffer ControlBuffer;
struct ControlBuffer
{
    unsigned char data[BUSTER_CONTROL_CAPACITY];
    size_t size;
};

typedef struct ControlOptions ControlOptions;
struct ControlOptions
{
    uint64_t shift;
    ControlFault fault;
    bool reorder;
    bool drop_comment;
    bool drop_file;
    bool multi_addrsig;
    bool reverse_addrsig;
    const char *comment;
    const char *file_name;
};

typedef struct ControlFixture ControlFixture;
struct ControlFixture
{
    ControlBuffer bytes;
    size_t section_index[BUSTER_CONTROL_SECTION_COUNT];
    size_t symbol_index[BUSTER_CONTROL_SYMBOL_COUNT];
    size_t section_count;
    size_t symbol_count;
    size_t section_headers;
};

typedef enum ControlMode
{
    BUSTER_CONTROL_COMPARE,
    BUSTER_CONTROL_READER
} ControlMode;

typedef struct ControlResult ControlResult;
struct ControlResult
{
    const char *name;
    bool expected;
    bool accepted;
    bool passed;
    char error[BUSTER_HP_ERROR_CAPACITY];
};

typedef struct ControlSuite ControlSuite;
struct ControlSuite
{
    ControlResult results[128];
    size_t count;
    size_t failures;
};

static void control_append(ControlBuffer *buffer, const void *data, size_t size)
{
    assert(size <= sizeof(buffer->data) - buffer->size);
    if (size != 0)
    {
        memcpy(buffer->data + buffer->size, data, size);
    }
    buffer->size += size;
    return;
}

static void control_align(ControlBuffer *buffer, size_t align)
{
    assert(align != 0 && (align & (align - 1)) == 0);
    size_t padding = (align - buffer->size % align) % align;
    assert(padding <= sizeof(buffer->data) - buffer->size);
    memset(buffer->data + buffer->size, 0, padding);
    buffer->size += padding;
    return;
}

static uint32_t control_append_string(ControlBuffer *strings, const char *value)
{
    uint32_t offset = (uint32_t)strings->size;
    control_append(strings, value, strlen(value) + 1);
    return offset;
}

static Elf64_Ehdr control_header(const ControlFixture *fixture)
{
    Elf64_Ehdr header;
    assert(fixture->bytes.size >= sizeof(header));
    memcpy(&header, fixture->bytes.data, sizeof(header));
    return header;
}

static void control_set_header(ControlFixture *fixture, Elf64_Ehdr header)
{
    memcpy(fixture->bytes.data, &header, sizeof(header));
    return;
}

static Elf64_Shdr control_section(const ControlFixture *fixture, ControlSection id)
{
    Elf64_Shdr section;
    size_t index = fixture->section_index[id];
    assert(index != SIZE_MAX && index < fixture->section_count);
    memcpy(&section, fixture->bytes.data + fixture->section_headers + index * sizeof(section), sizeof(section));
    return section;
}

static void control_set_section(ControlFixture *fixture, ControlSection id, Elf64_Shdr section)
{
    size_t index = fixture->section_index[id];
    assert(index != SIZE_MAX && index < fixture->section_count);
    memcpy(fixture->bytes.data + fixture->section_headers + index * sizeof(section), &section, sizeof(section));
    return;
}

static Elf64_Sym control_symbol(const ControlFixture *fixture, ControlSymbol id)
{
    Elf64_Shdr section = control_section(fixture, BUSTER_SECTION_SYMTAB);
    Elf64_Sym symbol;
    size_t index = fixture->symbol_index[id];
    assert(index != SIZE_MAX && index < fixture->symbol_count);
    memcpy(&symbol, fixture->bytes.data + section.sh_offset + index * sizeof(symbol), sizeof(symbol));
    return symbol;
}

static void control_set_symbol(ControlFixture *fixture, ControlSymbol id, Elf64_Sym symbol)
{
    Elf64_Shdr section = control_section(fixture, BUSTER_SECTION_SYMTAB);
    size_t index = fixture->symbol_index[id];
    assert(index != SIZE_MAX && index < fixture->symbol_count);
    memcpy(fixture->bytes.data + section.sh_offset + index * sizeof(symbol), &symbol, sizeof(symbol));
    return;
}

static Elf64_Rela control_relocation(const ControlFixture *fixture, ControlSection id, size_t index)
{
    Elf64_Shdr section = control_section(fixture, id);
    Elf64_Rela relocation;
    assert((index + 1) * sizeof(relocation) <= section.sh_size);
    memcpy(&relocation, fixture->bytes.data + section.sh_offset + index * sizeof(relocation), sizeof(relocation));
    return relocation;
}

static void control_set_relocation(ControlFixture *fixture, ControlSection id, size_t index, Elf64_Rela relocation)
{
    Elf64_Shdr section = control_section(fixture, id);
    assert((index + 1) * sizeof(relocation) <= section.sh_size);
    memcpy(fixture->bytes.data + section.sh_offset + index * sizeof(relocation), &relocation, sizeof(relocation));
    return;
}

static Elf64_Rela control_make_relocation(const ControlFixture *fixture, uint64_t offset, unsigned type, ControlSymbol symbol, int64_t addend)
{
    Elf64_Rela relocation = {0};
    relocation.r_offset = offset;
    relocation.r_info = ELF64_R_INFO(fixture->symbol_index[symbol], type);
    relocation.r_addend = addend;
    return relocation;
}

static ControlOptions control_options(uint64_t shift, ControlFault fault)
{
    ControlOptions options = {0};
    options.shift = shift;
    options.fault = fault;
    options.comment = "producer C";
    options.file_name = "input.c";
    return options;
}

static void control_fixture(ControlFixture *fixture, ControlOptions options)
{
    static const char *const names[BUSTER_CONTROL_SECTION_COUNT] =
    {
        "",
        BUSTER_CONTROL_HOT,
        ".data",
        ".bss",
        ".symtab",
        ".strtab",
        ".shstrtab",
        ".rela.hot",
        ".rela.data",
        ".llvm_addrsig",
        ".comment",
        ".note.GNU-stack"
    };
    ControlSection order[BUSTER_CONTROL_SECTION_COUNT] = {0};
    size_t order_count = 0;
    memset(fixture, 0, sizeof(*fixture));
    for (size_t i = 0; i < BUSTER_CONTROL_SECTION_COUNT; i += 1)
    {
        fixture->section_index[i] = SIZE_MAX;
        bool active = !(i == BUSTER_SECTION_ADDRSIG && options.fault == BUSTER_FAULT_MISSING_ADDRSIG) && !(i == BUSTER_SECTION_STACK && options.fault == BUSTER_FAULT_MISSING_STACK_NOTE) && !(i == BUSTER_SECTION_COMMENT && options.drop_comment);
        if (active)
        {
            order[order_count++] = (ControlSection)i;
        }
    }
    if (options.reorder)
    {
        order[1] = BUSTER_SECTION_DATA;
        order[2] = BUSTER_SECTION_HOT;
    }
    for (size_t i = 0; i < order_count; i += 1)
    {
        fixture->section_index[order[i]] = i;
    }
    fixture->section_count = order_count;

    ControlSymbol symbol_order[BUSTER_CONTROL_SYMBOL_COUNT] =
    {
        BUSTER_SYMBOL_NULL,
        BUSTER_SYMBOL_FILE,
        BUSTER_SYMBOL_SECTION,
        BUSTER_SYMBOL_FOO,
        BUSTER_SYMBOL_DATA,
        BUSTER_SYMBOL_EXTERNAL,
        BUSTER_SYMBOL_ALIAS
    };
    if (options.reorder)
    {
        symbol_order[1] = BUSTER_SYMBOL_FOO;
        symbol_order[2] = BUSTER_SYMBOL_SECTION;
        symbol_order[3] = BUSTER_SYMBOL_FILE;
    }
    if (options.fault == BUSTER_FAULT_ALIAS || options.fault == BUSTER_FAULT_AMBIGUOUS_SYMBOL)
    {
        symbol_order[4] = BUSTER_SYMBOL_ALIAS;
        symbol_order[5] = BUSTER_SYMBOL_DATA;
        symbol_order[6] = BUSTER_SYMBOL_EXTERNAL;
    }
    size_t symbol_order_count = options.fault == BUSTER_FAULT_ALIAS || options.fault == BUSTER_FAULT_AMBIGUOUS_SYMBOL ? 7 : 6;
    for (size_t i = 0; i < BUSTER_CONTROL_SYMBOL_COUNT; i += 1)
    {
        fixture->symbol_index[i] = SIZE_MAX;
    }
    size_t kept_symbols = 0;
    for (size_t i = 0; i < symbol_order_count; i += 1)
    {
        if (!(options.drop_file && symbol_order[i] == BUSTER_SYMBOL_FILE))
        {
            symbol_order[kept_symbols++] = symbol_order[i];
        }
    }
    symbol_order_count = kept_symbols;
    fixture->symbol_count = symbol_order_count;
    for (size_t i = 0; i < symbol_order_count; i += 1)
    {
        fixture->symbol_index[symbol_order[i]] = i;
    }

    ControlBuffer strings = {0};
    ControlBuffer symbol_bytes = {0};
    const unsigned char zero = 0;
    control_append(&strings, &zero, 1);
    for (size_t i = 0; i < symbol_order_count; i += 1)
    {
        ControlSymbol id = symbol_order[i];
        Elf64_Sym symbol = {0};
        const char *name = "";
        if (id == BUSTER_SYMBOL_FILE)
        {
            name = options.file_name;
            symbol.st_info = ELF64_ST_INFO(STB_LOCAL, STT_FILE);
            symbol.st_shndx = SHN_ABS;
        }
        else if (id == BUSTER_SYMBOL_SECTION)
        {
            symbol.st_info = ELF64_ST_INFO(STB_LOCAL, STT_SECTION);
            symbol.st_shndx = (Elf64_Section)fixture->section_index[BUSTER_SECTION_HOT];
        }
        else if (id == BUSTER_SYMBOL_FOO || id == BUSTER_SYMBOL_ALIAS)
        {
            name = id == BUSTER_SYMBOL_FOO || options.fault == BUSTER_FAULT_AMBIGUOUS_SYMBOL ? "foo" : "alias";
            symbol.st_info = ELF64_ST_INFO(STB_LOCAL, STT_FUNC);
            symbol.st_shndx = (Elf64_Section)fixture->section_index[BUSTER_SECTION_HOT];
            symbol.st_value = options.shift + (options.fault == BUSTER_FAULT_SYMBOL_OFFSET ? 1 : 0);
            symbol.st_size = options.fault == BUSTER_FAULT_SYMBOL_SIZE ? 9 : 8;
            symbol.st_other = options.fault == BUSTER_FAULT_SYMBOL_VISIBILITY ? STV_HIDDEN : STV_DEFAULT;
            if (options.fault == BUSTER_FAULT_HOT_SYMBOL_UNDERFLOW)
            {
                symbol.st_value = options.shift - 1;
            }
            if (options.fault == BUSTER_FAULT_HOT_SYMBOL_OVERFLOW)
            {
                symbol.st_value = UINT64_MAX;
            }
        }
        else if (id == BUSTER_SYMBOL_DATA)
        {
            name = "object";
            symbol.st_info = ELF64_ST_INFO(STB_GLOBAL, STT_OBJECT);
            symbol.st_shndx = (Elf64_Section)fixture->section_index[BUSTER_SECTION_DATA];
            symbol.st_size = 16;
        }
        else if (id == BUSTER_SYMBOL_EXTERNAL)
        {
            name = "external";
            symbol.st_info = ELF64_ST_INFO(STB_GLOBAL, STT_NOTYPE);
        }
        symbol.st_name = name[0] != 0 ? control_append_string(&strings, name) : 0;
        control_append(&symbol_bytes, &symbol, sizeof(symbol));
    }

    ControlBuffer hot_relocations = {0};
    ControlBuffer data_relocations = {0};
    unsigned relocation_type = options.fault == BUSTER_FAULT_UNKNOWN_RELOCATION ? 43 : R_X86_64_PC32;
    if (options.fault >= BUSTER_FAULT_TLSDESC_34 && options.fault <= BUSTER_FAULT_TLSDESC_36)
    {
        relocation_type = 34 + (unsigned)(options.fault - BUSTER_FAULT_TLSDESC_34);
    }
    ControlSymbol target = options.fault == BUSTER_FAULT_WRONG_TARGET ? BUSTER_SYMBOL_DATA : options.fault == BUSTER_FAULT_FILE_REFERENCED ? BUSTER_SYMBOL_FILE : BUSTER_SYMBOL_EXTERNAL;
    uint64_t relocation_offset = options.shift + 8 + (options.fault == BUSTER_FAULT_RELOC_OFFSET ? 1 : 0);
    if (options.fault == BUSTER_FAULT_RELOC_OVERFLOW)
    {
        relocation_offset = UINT64_MAX;
    }
    Elf64_Rela relocation = control_make_relocation(fixture, relocation_offset, relocation_type, target, -4);
    control_append(&hot_relocations, &relocation, sizeof(relocation));
    if (options.fault == BUSTER_FAULT_OVERLAP)
    {
        relocation = control_make_relocation(fixture, options.shift + 9, R_X86_64_PC32, BUSTER_SYMBOL_EXTERNAL, -4);
        control_append(&hot_relocations, &relocation, sizeof(relocation));
    }
    unsigned section_type = options.fault == BUSTER_FAULT_HOT_SECTION_GOT ? R_X86_64_GOTPCREL : options.fault == BUSTER_FAULT_PC_SECTION ? R_X86_64_PC32 : R_X86_64_64;
    int64_t section_addend = (int64_t)options.shift - (options.fault == BUSTER_FAULT_PC_SECTION ? 4 : 0);
    if (options.fault == BUSTER_FAULT_SECTION_ADDEND)
    {
        section_addend += 1;
    }
    if (options.fault == BUSTER_FAULT_SECTION_ADDEND_OUTSIDE)
    {
        section_addend = (int64_t)options.shift - 100;
    }
    if (options.fault == BUSTER_FAULT_SECTION_ADDEND_OVERFLOW)
    {
        section_addend = INT64_MIN;
    }
    relocation = control_make_relocation(fixture, 0, section_type, BUSTER_SYMBOL_SECTION, section_addend);
    control_append(&data_relocations, &relocation, sizeof(relocation));
    relocation = control_make_relocation(fixture, 8, R_X86_64_64, BUSTER_SYMBOL_FOO, options.fault == BUSTER_FAULT_NAMED_ADDEND ? 1 : 0);
    control_append(&data_relocations, &relocation, sizeof(relocation));

    ControlBuffer section_names = {0};
    uint32_t name_offsets[BUSTER_CONTROL_SECTION_COUNT] = {0};
    control_append(&section_names, &zero, 1);
    for (size_t i = 1; i < order_count; i += 1)
    {
        name_offsets[order[i]] = control_append_string(&section_names, names[order[i]]);
    }
    ControlBuffer hot_bytes = {0};
    assert(options.shift <= BUSTER_CONTROL_CAPACITY - 32);
    memset(hot_bytes.data, 0, (size_t)options.shift);
    memset(hot_bytes.data + options.shift, 'H', 32);
    hot_bytes.size = (size_t)options.shift + 32;
    if (options.fault == BUSTER_FAULT_HOT_BYTE)
    {
        hot_bytes.data[options.shift] = 'X';
    }
    if (options.fault == BUSTER_FAULT_PREFIX_BYTE && options.shift != 0)
    {
        hot_bytes.data[0] = 'X';
    }
    unsigned char data_bytes[16];
    memset(data_bytes, 'D', sizeof(data_bytes));
    if (options.fault == BUSTER_FAULT_DATA_BYTE)
    {
        data_bytes[0] = 'X';
    }
    unsigned char addrsig[12] = {0};
    size_t addrsig_size = 1;
    addrsig[0] = (unsigned char)fixture->symbol_index[options.fault == BUSTER_FAULT_ADDRSIG_TARGET ? BUSTER_SYMBOL_EXTERNAL : BUSTER_SYMBOL_FOO];
    if (options.multi_addrsig)
    {
        addrsig_size = 3;
        addrsig[0] = (unsigned char)fixture->symbol_index[options.reverse_addrsig ? BUSTER_SYMBOL_EXTERNAL : BUSTER_SYMBOL_FOO];
        addrsig[1] = (unsigned char)fixture->symbol_index[options.reverse_addrsig ? BUSTER_SYMBOL_FOO : BUSTER_SYMBOL_EXTERNAL];
        addrsig[2] = (unsigned char)fixture->symbol_index[BUSTER_SYMBOL_FOO];
    }
    if (options.fault == BUSTER_FAULT_ADDRSIG_DUPLICATE_LOSS)
    {
        addrsig_size = 2;
    }
    if (options.fault == BUSTER_FAULT_ADDRSIG_TRUNCATED)
    {
        addrsig[0] = 0x80;
    }
    if (options.fault == BUSTER_FAULT_ADDRSIG_OVERFLOW)
    {
        memset(addrsig, 0xff, 10);
        addrsig[10] = 1;
        addrsig_size = 11;
    }
    if (options.fault == BUSTER_FAULT_ADDRSIG_BAD_SYMBOL)
    {
        addrsig[0] = 127;
    }

    Elf64_Shdr sections[BUSTER_CONTROL_SECTION_COUNT] = {0};
    memset(fixture->bytes.data, 0, sizeof(Elf64_Ehdr));
    fixture->bytes.size = sizeof(Elf64_Ehdr);
    for (size_t i = 1; i < order_count; i += 1)
    {
        ControlSection id = order[i];
        Elf64_Shdr *section = &sections[i];
        const unsigned char *payload = NULL;
        size_t payload_size = 0;
        section->sh_name = name_offsets[id];
        section->sh_type = SHT_PROGBITS;
        section->sh_addralign = 1;
        if (id == BUSTER_SECTION_HOT)
        {
            section->sh_flags = SHF_ALLOC | SHF_EXECINSTR;
            section->sh_addralign = options.fault == BUSTER_FAULT_ALIGNMENT ? 2048 : 4096;
            payload = hot_bytes.data;
            payload_size = hot_bytes.size;
        }
        else if (id == BUSTER_SECTION_DATA || id == BUSTER_SECTION_BSS)
        {
            section->sh_flags = SHF_ALLOC | SHF_WRITE;
            section->sh_addralign = 8;
            payload = data_bytes;
            payload_size = sizeof(data_bytes);
            if (id == BUSTER_SECTION_BSS)
            {
                section->sh_type = SHT_NOBITS;
                payload_size = options.fault == BUSTER_FAULT_BSS_SIZE ? 9 : 8;
            }
            else if (options.fault == BUSTER_FAULT_GROUP)
            {
                section->sh_type = SHT_GROUP;
                section->sh_flags = SHF_GROUP;
            }
        }
        else if (id == BUSTER_SECTION_SYMTAB)
        {
            section->sh_type = SHT_SYMTAB;
            section->sh_flags = options.fault == BUSTER_FAULT_ALLOC_SYMTAB ? SHF_ALLOC : 0;
            section->sh_link = (Elf64_Word)fixture->section_index[BUSTER_SECTION_STRTAB];
            section->sh_info = (Elf64_Word)(symbol_order_count - 2);
            section->sh_addralign = 8;
            section->sh_entsize = sizeof(Elf64_Sym);
            payload = symbol_bytes.data;
            payload_size = symbol_bytes.size;
        }
        else if (id == BUSTER_SECTION_STRTAB || id == BUSTER_SECTION_SHSTRTAB)
        {
            section->sh_type = SHT_STRTAB;
            section->sh_flags = id == BUSTER_SECTION_STRTAB && options.fault == BUSTER_FAULT_ALLOC_STRTAB ? SHF_ALLOC : 0;
            payload = id == BUSTER_SECTION_STRTAB ? strings.data : section_names.data;
            payload_size = id == BUSTER_SECTION_STRTAB ? strings.size : section_names.size;
        }
        else if (id == BUSTER_SECTION_RELA_HOT || id == BUSTER_SECTION_RELA_DATA)
        {
            section->sh_type = id == BUSTER_SECTION_RELA_HOT && options.fault == BUSTER_FAULT_REL ? SHT_REL : SHT_RELA;
            section->sh_flags = SHF_INFO_LINK | (options.fault == BUSTER_FAULT_ALLOC_RELA ? SHF_ALLOC : 0);
            section->sh_link = (Elf64_Word)fixture->section_index[BUSTER_SECTION_SYMTAB];
            section->sh_info = (Elf64_Word)fixture->section_index[id == BUSTER_SECTION_RELA_HOT ? BUSTER_SECTION_HOT : BUSTER_SECTION_DATA];
            section->sh_addralign = 8;
            section->sh_entsize = sizeof(Elf64_Rela);
            payload = id == BUSTER_SECTION_RELA_HOT ? hot_relocations.data : data_relocations.data;
            payload_size = id == BUSTER_SECTION_RELA_HOT ? hot_relocations.size : data_relocations.size;
        }
        else if (id == BUSTER_SECTION_ADDRSIG)
        {
            section->sh_type = BUSTER_HP_ADDRSIG;
            section->sh_flags = SHF_EXCLUDE;
            section->sh_link = (Elf64_Word)fixture->section_index[BUSTER_SECTION_SYMTAB];
            payload = addrsig;
            payload_size = addrsig_size;
        }
        else if (id == BUSTER_SECTION_COMMENT)
        {
            section->sh_flags = SHF_MERGE | SHF_STRINGS | (options.fault == BUSTER_FAULT_ALLOC_COMMENT ? SHF_ALLOC : 0);
            section->sh_entsize = 1;
            section->sh_link = options.fault == BUSTER_FAULT_UNKNOWN_LINKED_METADATA ? (Elf64_Word)fixture->section_index[BUSTER_SECTION_SYMTAB] : 0;
            payload = (const unsigned char *)options.comment;
            payload_size = strlen(options.comment) + 1;
        }
        else if (id == BUSTER_SECTION_STACK)
        {
            section->sh_flags = options.fault == BUSTER_FAULT_EXEC_STACK ? SHF_EXECINSTR : 0;
        }
        control_align(&fixture->bytes, section->sh_addralign);
        section->sh_offset = fixture->bytes.size;
        section->sh_size = payload_size;
        if (section->sh_type != SHT_NOBITS)
        {
            control_append(&fixture->bytes, payload, payload_size);
        }
    }
    control_align(&fixture->bytes, 8);
    fixture->section_headers = fixture->bytes.size;
    control_append(&fixture->bytes, sections, order_count * sizeof(sections[0]));
    Elf64_Ehdr header = {0};
    memcpy(header.e_ident, ELFMAG, SELFMAG);
    header.e_ident[EI_CLASS] = ELFCLASS64;
    header.e_ident[EI_DATA] = ELFDATA2LSB;
    header.e_ident[EI_VERSION] = EV_CURRENT;
    header.e_type = ET_REL;
    header.e_machine = EM_X86_64;
    header.e_version = EV_CURRENT;
    header.e_shoff = fixture->section_headers;
    header.e_ehsize = sizeof(header);
    header.e_shentsize = sizeof(Elf64_Shdr);
    header.e_shnum = (Elf64_Half)order_count;
    header.e_shstrndx = (Elf64_Half)fixture->section_index[BUSTER_SECTION_SHSTRTAB];
    control_set_header(fixture, header);
    if (options.fault == BUSTER_FAULT_BAD_MAGIC)
    {
        fixture->bytes.data[0] = 0;
    }
    if (options.fault == BUSTER_FAULT_TRUNCATE)
    {
        fixture->bytes.size -= 1;
    }
    return;
}

static void control_record(ControlSuite *suite, const char *name, bool expected, bool accepted, const char *error)
{
    assert(suite->count < BUSTER_ARRAY_COUNT(suite->results));
    ControlResult *result = &suite->results[suite->count++];
    result->name = name;
    result->expected = expected;
    result->accepted = accepted;
    result->passed = expected == accepted;
    snprintf(result->error, sizeof(result->error), "%s", error);
    suite->failures += result->passed ? 0 : 1;
    printf("%s %s%s%s\n", result->passed ? "PASS" : "FAIL", name, !result->passed && error[0] != 0 ? ": " : "", !result->passed ? error : "");
    return;
}

static void control_run(ControlSuite *suite, const char *name, const ControlFixture *base, const ControlFixture *variant, uint64_t shift, bool expected, ControlMode mode)
{
    HpElf left = {0};
    HpElf right = {0};
    HpObjectProof proof = {0};
    char error[BUSTER_HP_ERROR_CAPACITY] = {0};
    HpBytes left_bytes =
    {
        base->bytes.data,
        base->bytes.size
    };
    HpBytes right_bytes =
    {
        variant->bytes.data,
        variant->bytes.size
    };
    bool accepted = hp_elf_read(left_bytes, &left, error);
    if (accepted && mode == BUSTER_CONTROL_COMPARE)
    {
        accepted = hp_elf_read(right_bytes, &right, error);
        if (accepted)
        {
            accepted = hp_elf_compare_objects(&left, &right, BUSTER_CONTROL_HOT, shift, &proof, error);
        }
    }
    control_record(suite, name, expected, accepted, error);
    hp_object_proof_free(&proof);
    hp_elf_free(&left);
    hp_elf_free(&right);
    return;
}

static void control_pair(ControlSuite *suite, const char *name, ControlOptions base_options, ControlOptions variant_options, bool expected)
{
    ControlFixture base;
    ControlFixture variant;
    control_fixture(&base, base_options);
    control_fixture(&variant, variant_options);
    control_run(suite, name, &base, &variant, variant_options.shift, expected, BUSTER_CONTROL_COMPARE);
    return;
}

